$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ csrfCheck(); $id=trim($_POST['identifier']??''); $pw=$_POST['password']??''; $s=$koneksi->prepare('SELECT id_user,nama,username,email,password,role,kelas,foto,status_akun FROM users WHERE username=? OR email=? LIMIT 1'); $s->bind_param('ss',$id,$id); $s->execute(); $u=$s->get_result()->fetch_assoc(); if(!$u||!password_verify($pw,$u['password'])) $error='Username/email atau password tidak sesuai.'; elseif($u['status_akun']!=='aktif') $error='Akun belum aktif. Hubungi admin sekolah.'; else { session_regenerate_id(true); unset($u['password'],$u['status_akun']); $_SESSION['user']=$u; logActivity($koneksi,(int)$u['id_user'],'Login','Pengguna masuk ke SIBARA.'); redirect($u['role'].'/dashboard.php'); } }
$pageTitle='Masuk'; require __DIR__.'/includes/header.php'; ?>
